    "desc": "与{{user}}命运永久绑定的被动增益天赋，所有真正归属{{user}}的正向收益，到手瞬间自动完成去杂、补全、升级，…",
    "content": `<收获升级>

<简介>
与{{user}}命运永久绑定的被动增益天赋，所有真正归属{{user}}的正向收益，到手瞬间自动完成去杂、补全、升级，从“能用”直接变成“同阶最优”或“跨代成熟版”，无操作门槛、无额外消耗。

<本质>
仅对正向收益做同类优化，不改变收益核心属性，自动剔除杂质陷阱，让{{user}}拿到的每一样东西天然比原版更实用、更稳定、更适配自身需求。

<主收益轴>
个人型，核心收益为所有到账正向收益的品质永久提升，附属收益为联动其他金手指产物的自动整合优化。

<触发源>
· 被动触发：正向收益实际归属{{user}}的瞬间自动触发
· 联动触发：其他金手指产出碎片、边角料、衍生物时自动触发
· 场景触发：收益暂时不可用、跨世界入账时自动触发保护性暂存升级
· 记录触发：累计触发达到阈值时自动触发阶段升级

<核心能力>
1. 【正向收录】自动判定收益性质，仅对正向收益生效：
   - 可生效范围：实体物资、修为天赋、技能功法、好感状态、机缘传承、其他金手指产出的所有正向产物
   - 自动剔除：杂质、缺陷、副作用、冗余内容，若收益本质为陷阱、诅咒、污染则直接判定无效，不会误触发升级
2. 【自动完形】通过正向判定的收益自动完成升级，二选一取最优结果：
   - 同阶收益直接补全为同阶完美态，修复所有瑕疵，提升30%-100%的实用效果
   - 成熟度不足的半成品、碎片，直接跃升为下一级成熟标准版，跨过实用门槛
   - 升级不改变收益核心用途（剑仍是剑、疗伤药仍是疗伤药），优先适配{{user}}当前需求，无副作用，外界自动合理解释为“运气好拿到精品”“天赋异禀完美提纯”，不会暴露天赋存在
3. 【联动优化】自动处理其他金手指产出的低质、碎片化衍生收益：
   - 同源碎片自动无损融合提纯，变成完整可用的高价值成品
   - 食之无味的边角料优先升级为明确可用的实用道具，不浪费任何收益
   - 升级仅提升完成度、纯度、实用性，不会无中生有把低阶素材改成高阶神物

<成长阶段>
升级条件与{{user}}正常获取收益的行为深度绑定，自然推进即可升阶，无额外苛刻要求：
1. 【初阶增幅】（初始阶段）
   升级幅度：同阶收益提升30%效果，半成品质升为普通成熟品
   升级条件：累计触发100次收益升级
   升级后解锁：中阶完形阶段
2. 【中阶完形】
   升级幅度：同阶收益提升60%效果，半成品质升为精品成熟品
   升级条件：累计触发1000次收益升级
   升级后解锁：高阶升华阶段
3. 【高阶升华】
   升级幅度：同阶收益提升100%效果，残次品直接升为同阶完美态
   升级条件：累计触发10000次收益升级
   升级后解锁：终阶点化阶段
4. 【终阶点化】（满阶）
   升级幅度：同阶收益提升200%效果，普通品可跃升为下一级完美态，低阶边角料有概率觉醒特殊稀有属性

<状态栏>
持有者：{{user}}
当前阶段：[初阶增幅/中阶完形/高阶升华/终阶点化]
当前升级幅度：X%
累计触发次数：X次
当前进度：X%
下一阶段：[阶段名]
下一阶段条件：累计触发X次收益升级

<结算逻辑>
1. 到账结算：收益归属{{user}}瞬间自动完成判定、去杂、升级，即时到账升级后的产物
2. 复合结算：多组件混合收益自动拆分，正向部分分别升级，杂质直接剔除，同源碎片自动融合
3. 联动结算：其他金手指产出的衍生物自动优化，优先升级为可用状态
4. 保护性结算：收益暂时不可用时自动暂存并完成升级，等可用时直接发放升级后的产物，不会吞收益

<回执模板>
本次触发：[收益到账/联动优化/保护性暂存/阶段升级]
结算内容：[简述事由，如「获得普通铁剑一柄，判定为正向收益」]
本次收益：[明确列出升级结果，如「铁剑自动升级为同阶完美态，锋利度+50%，自带破甲效果」]
进度变化：[当前阶段进度变动，如「初阶增幅阶段进度+1%，当前45%」]
下一步提示：[可选行动建议，如「该剑可直接用于当前阶段战斗」]

<法则>
1. 仅对真正的正向收益生效，陷阱、诅咒、污染等负面内容不会触发升级，也不会被洗白
2. 升级仅做同类优化，不改变收益核心属性，不会无中生有篡改收益本质
3. 所有升级默认适配{{user}}当前最实用的方向，无需手动调整

<终极指向>
{{user}}拿到的所有收益天然比他人的同款强出一个层级，积少成多形成滚雪球优势，凡归于{{user}}之物，全为同阶最优，最终实现“拿到即赚到，收获即强化”的永久增益。

</收获升级>`
