——力量模板
——境界概念
——功法知识
——科技造物
——血脉样本
——法则碎片
——情报坐标
——特殊服务

<定价规律>
源力万市对商品的定价，综合以下因素决定：
——商品本身的位格与稀缺度；
——对购买者的兼容程度；
——所在世界的接受能力；
——是否可量产、是否可复用；
——是否会在后续为平台带来更大收益。

因此，相同数额的源力，在不同商品上体现出的价值并不一致。
万市的定价目标不仅是获利，也是引导成长、制造回流与放大长期收益。

