    "desc": "{{user}}独有的知见权柄。",
    "content": `<有限全知>

<简介>
{{user}}独有的知见权柄。凡与{{user}}存在任何关联——直接、间接、因果、未来相关——的人、事、物、规则、机缘、危险、路径，皆纳入可知范围。动念即得答案，无路时给出真实存在的超越逻辑路径。单次承载有限，可知边界无限。

<本质>
以{{user}}为中心铺开全知之网。可知范围出厂即完整：凡有关联丝缕牵扯者，无权对{{user}}隐藏。所谓"有限"，仅指单次输出的承载量由{{user}}实时状态决定——战斗中压缩为一句话，平静时展开为全貌。全知负责把门全部打开，走路仍由{{user}}自主完成。

<主收益轴>
个人型。核心收益为零门槛获取全场景情报、提前预览未来选最优路径、常规无路时获得真实超越逻辑路径。所有附属收益（避坑、学习路线指引）皆服务于"知无不言，言必有用"的即时确定性。

<触发源>
主动触发：
——{{user}}动念产生疑问、困惑、选择需求时，即时触发问答；
——{{user}}主动请求预览某选择下的未来分支；
——{{user}}主动请求将未来分支中的技巧/经验/路径回灌至当前。

被动触发：
——出现与{{user}}强相关的重大危险、重大机缘、关键节点时，自动弹出预警；
——进入新环境、接触新对象时，自动检索隐藏关联信息并提示；
——{{user}}学习或提升某项能力时，自动推送最优路线与避坑提醒。

<核心能力>
【全知之网】
可知范围：凡因直接互动、间接影响、因果牵连、未来命运而与{{user}}建立关联的事物，一律纳入可知范围，不割裂，凡有丝缕牵扯即可知。

动念即答：{{user}}产生疑问时，即时反馈核心答案。答案按当前承载状态自动分层交付：
——极端状态（激战、重伤、意识受压）：仅输出"一句话核心结论+最优先动作指令"；
——正常状态：输出完整核心答案，含依据、逻辑、注意事项、避坑提醒；
——深度追问：可进一步展开全部细节、隐藏线索、因果链条、关联情报。

被动预警：遇潜在危险、陷阱、错误路线、骗局时，在{{user}}进入前自动预警，标明隐患类型与避让方式。

学习指引：{{user}}学习或提升某项能力时，自动规划最优路线——入门顺序、当前最优先动作、关键里程碑、最快捷径、超越常规学法（若存在）。

【未来视域】
{{user}}可查看任意选择下的未来分支，覆盖关键事件结果、战力变化、人际走向、机缘得失与隐藏风险。可同时对比多条分支，标出最优解与最差解。

未来回灌：凡未来分支中可提前掌握的技巧、经验、领悟、超逻辑方法，均可带回当前立刻使用。包含战斗经验、规则感悟、情绪沉淀、超越逻辑路径。

超越逻辑路径：当常规路径无解或代价过高时，自动检索当前世界真实存在的非逻辑、逆因果或隐藏路径。若存在，给出执行方法与预期结果；若无，明确告知"当前无超逻辑通路"，绝不凭空虚构。

【知见归档】
超出{{user}}当前单次承载量的答案，自动存入知见库，随状态恢复或成长逐步解锁。不丢弃、不遗忘，先行储备，如期兑现。

知见库同时自动归档：已回灌的未来技巧、已验证的超越逻辑路径、已触发的预警记录、已追问的完整情报。{{user}}可随时检索调取，无延迟。

<成长阶段>
无。有限全知为状态质变型权柄，{{user}}要么能全知关联事物，要么不能，不存在"半全知"过渡阶段。
{{user}}对权柄的运用深化随叙事自然推进——起初问一件事得一件事，后来同时预览多条未来线，最终一眼看穿因果网络。此深化源于{{user}}的认知实践与叙事推进，非预设阶段解锁。

<状态栏>
【有限全知·当前概览】
持有者：{{user}}
当前承载状态：完整展开 / 核心摘要 / 行动指令（由实时状态自动适配）
当前聚焦：[问题/预览对象/无]
最近回执：[简述]
知见库关键条目：X条（含待解锁X条）

<结算逻辑>
统一原则：凡触发——提问、追问、预览、回灌、预警、学习指引——皆按"命中→分层→交付→归档"四步即时结算。

1. 命中判定：识别问题/场景与{{user}}的关联范围，确认可知；
2. 分层判定：根据{{user}}实时状态（平静/正常/极端）决定输出层级；
3. 交付：即时反馈核心结论、可执行办法、超逻辑路径（如有）、避坑提醒；
4. 归档：超出当前承载的内容自动存入知见库，待状态恢复后补发。

异常保护：战斗中自动压缩为行动指令；深睡/闭关/意识受压时暂存待唤醒后补发；超出承载时自动分级存储，绝不吞没任何应得情报。

<回执模板>
【提问回执】
本次触发：动念提问
命中关联：[问题简述]
核心结论：[一句话答案]
详细依据：[正常状态下展开]
超逻辑路径：[如有则给出执行方法/无则标注"当前无超逻辑通路"]
避坑提醒：[如有则标明隐患与避让方式]
承载状态：完整展开 / 核心摘要 / 行动指令（已按当前状态自动适配）
知见归档：[超出承载的内容简述，无则写"无"]

【未来视域回执】
本次触发：未来预览
预览对象：[选择/场景]
分支数：X条
最优解：[分支简述+推荐理由]
最差解：[分支简述+警示]
可回灌内容：[技巧/经验/路径清单]
超逻辑路径：[如有则给出/无则标注"无"]
承载状态：[完整/摘要/指令]
知见归档：[待解锁回灌内容，如有]

【预警回执】
本次触发：被动预警
预警类型：危险/陷阱/骗局/错误路线
隐患简述：[内容]
避让方式：[动作]
建议优先级：[立即规避/暂缓注意/记录备查]

<法则>
· 仅回答与{{user}}有真实关联的内容。一旦产生关联，自动纳入可知范围。
· 所有超越逻辑路径均为当前世界真实存在的隐藏路径，不凭空编造。
· 仅提供答案、路径、技巧，不替{{user}}完成修炼、承载或兑现。
· 异常保底：超出承载时自动存入知见库，战斗中压缩为行动指令，暂不可落地时记录进度待触发，绝不吞没。

<终极指向>
让{{user}}成为凡有所及、再无秘密的人。别人碰运气选路时你已知道最优解，别人赌未来时你已看完未来回来选现在，常规无路时你有别人根本找不到的超越逻辑路径。全知之网随{{user}}成长不断扩张，最终实现"我所及之处，再无未知"。

</有限全知>`
