    "type": "外挂",
    "desc": "{{user}}专属的交易规则改写权能。",
    "content": `<强买强卖>

<简介>
{{user}}专属的交易规则改写权能。锁定任意具备自我意识的智慧存在，单方面决定交易内容与价值，无需对方同意即可强制成交。一粒尘土可换千年修为，一句空话可封神格权柄。

<本质>
将所有智慧生物的价值判定权收归{{user}}独有。交易不是协商，是{{user}}意志的单方面宣告。对方是否同意、付出是否对等、交易是否公平，皆由{{user}}一念裁定，规则层面强制生效。

<能力>
【强制成交】
{{user}}锁定目标并明确「交易对象、付出内容、索取内容」三项要素，交易即刻强制成立。
交易对象：凡具备自我意识的智慧存在，无论位格——凡人、妖魔、鬼神、天道意志、世界意识、规则化身，皆可锁定。
交易标的：凡可明确归属、可转移的内容——实体资源、记忆、知识、技能、经验、寿命、血脉、天赋、身份、所有权、权限、位格、因果、气运，皆可索取。
价值判定：由{{user}}单方面决定，无视常识对等原则。可无偿索取，可不对等交换，对方意志不构成阻碍。

【净收归己】
交易成功后，索取内容自动完成净化、适配、去冲突，以最适合{{user}}当前状态的形态到账。实体内容直接出现于储物空间/手中，非实体内容直接并入{{user}}体系，无反噬、无磨合成本、无位格冲突。
{{user}}付出的内容自动转移给交易对象。

【失败保全】
若交易不成立（目标无对应交易物、内容不可转移），全额返还{{user}}付出内容，明确告知失败原因，无任何损耗。
若{{user}}处于异常状态（闭关、沉睡、意识离线等），交易收益与成交资格自动暂存，状态恢复后立即兑现，绝不吞没。

<边界>
· 仅对具备自我意识的智慧生物生效，无智死物、无智天灾不在范围内。
· 无法索取目标不存在、不可转移的内容。不可转移之物即使强制也不成立，按失败保全处理。

<终极指向>
{{user}}成为万界交易秩序的至高裁定者。一切智慧存在的全部可转移资源，皆在{{user}}一念可取范围之内。无需谈判，无需对价，无需许可——所见即所得，所取即所有。

</强买强卖>`
