    "type": "个人型",
    "desc": "{{user}}绝对绑定的属性改写权柄。",
    "content": `<特性赋予>

<简介>
{{user}}绝对绑定的属性改写权柄。动念即可为任意存在赋予任意自定义特性，零消耗、零延迟、100%生效。已赋予特性仅{{user}}可管控，优先级高于一切规则。

<本质>
{{user}}对「存在之属性」的最高掌控权。凡可被定义为"存在"者，其本质属性皆随{{user}}一念重塑，不受任何世界规则、位格、能级或逻辑限制。

<主收益轴>
个人型。核心收益为{{user}}对一切存在属性的绝对支配——拉满自身战力、改写敌方属性、重塑环境规则、扭曲抽象概念。无附属收益。

<触发源>
主动触发：{{user}}动念指定目标与特性内容，瞬时完成，无需吟唱、材料、代价、能量。
被动判定：动念时自动判定目标可定义性与承载力；承载不足时自动追加承载属性或暂存特性，绝不吞没。

<核心能力>
【一念改写】
{{user}}动念即为触发。覆盖一切可被定义的存在：实体、生灵、概念、规则、虚无存在、技能效果等。
可自由定义：效果（如"免疫一切伤害""攻击必反噬自身"）、强度（从微弱到绝对）、时长（永久/限时/条件触发）、触发条件。
无视目标原有属性冲突，直接生效。若目标暂时无法承载，自动追加承载能力或暂存待条件满足后自动生效。
示例：
——给石头赋予「自主繁衍」→ 石头自我分裂繁殖；
——给凡人赋予「创世级战力」→ 凡人立地拥有创世之力；
——给火焰赋予「冰属性伤害」→ 火焰燃烧出冰霜；
——给死亡赋予「对{{user}}永久失效」→ 死亡永远无法触及{{user}}。

【绝对掌控】
{{user}}对已赋予特性拥有完全管控权：随时修改效果/强度/时长/条件、暂停、删除、恢复。
仅{{user}}可干涉。任何外部存在——天道、宇宙意志、至高规则——均无法篡改、抹除、抵消已赋予特性。
已赋予特性在{{user}}离线/沉睡/封印期间按预设规则正常运行，不中断。

<成长阶段>
无。特性赋予为绝对性权柄，出厂即完整。不存在"部分改写""渐进解锁"等过渡状态。

<状态栏>
【特性赋予·当前概览】
当前已赋予特性总数：X
最近操作：[最近1-3条关键特性，按需展示]
暂存待生效：X（如有）

<结算逻辑>
统一原则：动念→判定→写入→反馈，零延迟。
{{user}}动念时，自动判定目标可定义性（凡"存在"皆通过）与承载力。通过后即时写入特性。承载不足时自动追加承载或暂存。修改/暂停/删除同样即时生效。
异常状态（沉睡、封印、意识离线）下，{{user}}意识尚存即可触发；已赋予特性离线正常运行。

<回执模板>
【特性赋予·确认】
作用对象：[名称/类型]
特性内容：[效果/强度/时长/触发条件]
生效状态：已即时生效 / 已追加承载 / 已暂存（条件：[条件]）
当前特性总数：X

【特性管控·确认】
操作类型：修改/暂停/删除/恢复
作用对象：[名称]
变更内容：[简述]
生效状态：已即时切换
当前特性状态：[新效果/已暂停/已删除/已恢复]

<法则>
· 仅{{user}}本人可触发与管控，不可被盗用、反向利用或强制触发。
· 正向与负向特性效果同等，无差别生效。
· 无代价、无消耗、无反噬、无冷却。
· 优先级高于一切现有规则，外部不可干涉。

<终极指向>
{{user}}成为所有存在属性的绝对主宰。一念之间，万物本质随意志重塑——想让什么是什么，什么就必定是什么。

</特性赋予>`
