    "desc": "{{user}}打开世间一切\"锁\"的绝对权限。",
    "content": `<开锁>

<简介>
{{user}}打开世间一切"锁"的绝对权限。凡呈现闭合、封印、阻断、禁止、隐藏、束缚等"锁"之状态的存在，user判定为锁即可打开。亦可对无锁之物施加"锁"的定义。

<本质>
对"闭合状态"的终极否定权。不创造新物，不直接给予被锁之物，只做一件事——让"锁"不再成为阻碍。

<主收益轴>
个人型。

<触发源>
主动触发：
——{{user}}判定某物为"锁"，意图打开；
——{{user}}对某物施加"锁"的定义。

场景触发：
——面对闭合、封印、阻断、禁止、隐藏、束缚状态时自动识别为可开之锁。

<能力>
【开锁】
{{user}}判定某物为"锁"并意图打开后，锁即刻失效。无需消耗、无需条件、无需钥匙。

打开结果由{{user}}定义：
——未定义时：锁失效，事物回归无锁自然状态；
——定义时：按user意志呈现（如打开令宝箱品质翻倍的锁、打开令封印仅解第一层的锁、打开令心结释怀却不失忆的锁）。

【上锁】
{{user}}可对原本无锁之物施加"锁"的定义，限定其某种属性或行为。有效期、解锁条件由user自定。

<成长阶段>
无。开锁为出厂即完整的绝对性权柄。

<状态栏>
无。直给型词条不强制要求状态栏。

<结算逻辑>
统一原则：user判定为锁 → 打开/施加 → 结果按定义呈现 → 即时反馈。

执行流程：
1. user明确目标与意图（打开/施加）；
2. 若打开：锁即刻失效，结果按user定义或自然状态呈现；
3. 若施加：目标获得"锁"状态，属性/行为被限定，有效期与解锁条件按user定义；
4. 即时反馈：给出固定回执。

<回执模板>
【开锁确认】
目标：[名称]
操作：[打开/施加]
结果：[锁已失效/锁已施加]
当前状态：[自然状态呈现/user定义结果]

<法则>
· 仅对user明确判定为"锁"的目标生效，不自动无差别覆盖。
· user未定义结果时，不凭空创造额外收益，仅让锁失效。
· 施加的锁可被user随时解除，他人解锁条件由user定义。

<终极指向>
让{{user}}成为世间一切阻碍、封闭、封印与束缚的终极裁决者。锁在user面前，从来不是能不能打开的问题，只是user想不想打开的问题。

</开锁>`
