    "desc": "两极反转，是将一切作用于{{user}}自身的效果极性永久颠倒的被动法则。",
    "content": `<两极反转>

<简介>
两极反转，是将一切作用于{{user}}自身的效果极性永久颠倒的被动法则。
增益化为灾异，灾异化为增益——恩赐与诅咒在{{user}}身上融为一体，无从区分。

<本质>
两极反转的本质，是效应极性的强制改写。
它不改变力量的数量与流向，只扭转其“有利/有害”的符号。
当一段能量、一道法术、一种状态试图触及{{user}}时，法则先将其极性翻转，然后才允许其生效。

<能力>
【常驻翻转】
所有来自任何源头（包括{{user}}自己主动施加）的、针对{{user}}的、具有明确极性的效果，都将被自动反转：
- 增益（治疗、强化、护盾、祝福、增益状态等）→等量的灾异（腐蚀、弱化、诅咒、减益状态等）
- 灾异（伤害、诅咒、弱化、减益状态等）→等量的增益（治疗、强化、祝福、增益状态等）

反转精确匹配原始效果的强度、持续时间、影响范围，仅极性反转。
此过程不消耗任何资源，不由{{user}}控制，持续存在。

【感知预读】
{{user}}能够本能感知到任何即将施加于自身的效果的原始性质与反转后性质，从而预判并利用。

【转换实例】
以下仅为常见映射，实际遵循法则自动匹配最合理结果：
- 治疗法术 → 腐蚀能量（伤害）
- 物理攻击 → 生命或护甲回复
- 力量增强状态 → 力量衰弱状态
- 防御削弱诅咒 → 防御强化祝福
- 护盾效果 → 持续侵蚀光环
- 即死判定 → 完全复活或绝对庇护
- 沉默封印 → 灵言增幅
- 致盲 → 超感知视野
- 元素抗性提升 → 元素易伤（但可能变为其他补偿）
- 减速效果 → 加速效果
- 中毒 → 持续再生

若一次效果同时包含增益与减益成分，法则以其主导极性判定；若无法判定主导，则可能按比例部分反转，或保持原状（极少出现）。

<边界>
【必定生效】
只要一个效果被世界法则判定为具有明确有益或有害取向，反转必定发生。不存在抗性抵抗或等级豁免。

【不溯及固有】
{{user}}的基础生物本能（呼吸、基础代谢、自然生命微量恢复）不受影响；{{user}}的种族本质、灵魂核心等固有属性也不被视为“效果”，故不会反转。

【自身被动技能】
{{user}}自身拥有的任何常驻被动技能或光环，若会持续对{{user}}产生增益或减益效果，则其每次触发或每周期结算同样会被反转。这意味着{{user}}的自身增益被动将变成有害，而自身减益被动将变成有益。{{user}}需要谨慎选择自身能力配置。

【仅限自身】
此法则仅影响{{user}}成为目标时的效果。{{user}}对他人或环境施加的效果正常运作。

【不可控】
{{user}}无法关闭、削弱或暂停这个法则。它恒定生效。

【中性效果】
完全中性、无正负之分的效应（如普通信息传递、空间坐标标记等）不会被反转。

【反转后效果正常结算】
反转后的治疗、伤害、状态等遵循正常的规则（可能被护甲减免、被抗性影响等），只是极性与原效果相反。

<终极指向>
两极反转将{{user}}置于一个矛盾的核心：祝福与诅咒在{{user}}身上等同。{{user}}将学会利用这一法则，将敌人的杀招化作甘露，将自身的弱点化为盔甲。最终，{{user}}不再被极性的幻象所困，而是直视一切效果的本质——力量本身无善恶，只有驾驭者定义其价值。

</两极反转>`
