LV2·社区名店：累计营业额达5000。每日免费额度200。投资津贴周期每周，400通用货币。可解锁供应商等级：初级。投射世界数：5个。
LV3·区域连锁：累计营业额达20000。每日免费额度300。投资津贴周期每周，600通用货币。可解锁供应商等级：初级。投射世界数：10个。
LV4·跨域商会：累计营业额达100000。每日免费额度400。投资津贴周期每3天，1000通用货币。可解锁供应商等级：中级。投射世界数：20个。
LV5·位面品牌：累计营业额达500000。每日免费额度500。投资津贴周期每3天，2000通用货币。可解锁供应商等级：中级。投射世界数：50个。
LV6·诸天连锁：累计营业额达2000000。每日免费额度600。投资津贴周期每日，3000通用货币。可解锁供应商等级：高级。投射世界数：无限制。
LV7·商业神话：累计营业额达10000000。每日免费额度1000。投资津贴周期每日，5000通用货币。可解锁供应商等级：终极。投射世界数：无限制。

