    "desc": "{{user}}专属的描述改写权能。",
    "content": `<描述改写>

<简介>
{{user}}专属的描述改写权能。世间一切存在皆有其描述，{{user}}对任意描述的改写将直接重构现实的第一因，使新描述成为从一开始就是如此的本源事实。

<本质>
将语言与文字升格为因果的底层接口。{{user}}的意图通过描述直达现实本源，绕过一切中间过程与阻力，直接重写存在的定义。

<主收益轴>
个人型。

<触发源>
主动触发：{{user}}以任意方式表达改写意图，指定目标描述与改写内容。
被动触发：{{user}}遭遇针对自身描述的篡改企图时，反溯免疫自动生效，篡改失败。
场景触发：{{user}}进入任意存在描述的世界时，改写权能即刻可用。

<核心能力>
【触发方式】
{{user}}以口述、书写、默念、手势、意念波动等任意方式表达改写意图，指定目标描述与改写内容，即刻生效。无媒介、无消耗、无冷却。

【改写范围】
凡可被语言、文字、概念描述的存在，皆可作为目标：
——他人正在说、已说、将说的话；
——书面文字、物品描述、人物设定、事件记录；
——世界法则、物理常数、因果链节点。

【第一因重构】
改写不修改当下结果，而是改写本源事实。现实以新描述为唯一真值重新演算，历史、记忆、物证、因果链自动修正以匹配新版本。唯{{user}}保留改写前的原始记忆。

【语义裁定】
改写以{{user}}的真实意图为最高准则，不受文字歧义、诡辩逻辑、规则咬文嚼字干扰。存在多种解读可能时，现实自动选择最利于{{user}}的方式实现。

【描述锁定】
{{user}}可对任意已完成的改写附加锁定。被锁定的描述成为不可动摇的绝对事实，此后任何力量包括其他改写能力、因果律操作、世界意志修正均无法再次更改。锁定无数量上限，无维持消耗。

【反溯免疫】
{{user}}自身的描述不可被任何外力改写。
{{user}}以外的任何存在均无法感知、观测、理解或记录此权能的存在、运作过程与产生结果。他人只会认定现实本就如此，任何追溯改写痕迹的手段均失败或指向错误结论。
任何非{{user}}的存在无法以任何形式触发、引导、干扰、借用、窃取或转移此权能。即便{{user}}处于精神控制、灵魂囚禁、存在抹消等异常状态，此权能仅响应{{user}}本人的真实意志。

<示例>
【人物命运改写】
原描述：历史文献记载他是导致世界陷入苦难的罪魁祸首。
改写为：他拼尽全力阻止末日降临，虽然最终大灾变还是发生了，但他依然是拯救世界的英雄。
结果：此人从出生起的全部人生轨迹、他人记忆、历史记录、因果链全部重构。世界认定他从未作恶，唯{{user}}记得他原本是罪魁祸首。

【即时话语改写】
原描述：敌人正在说今天我一定要打死你。
改写为：今天我一定要跪死你。
结果：敌人真心认定这是自己的本意，随即跪下，认为跪死{{user}}是自己毕生的追求。周围所有听到的人的记忆同步修正。

【契约法则改写】
原描述：契约条款写着签署者须献出灵魂作为代价。
改写为：签署者将获得对方的灵魂作为馈赠。
结果：契约本源逆转，恶魔的灵魂自动归于{{user}}。所有因果链以新条款为唯一真值运行，契约的物理文本与历史存档同步重写。

<轻量化状态栏>
【描述改写】
持有者：{{user}}
已锁定描述数：X
当前反溯免疫：生效中
当前可触发动作：发起改写 / 附加锁定

<结算与回执>
【普通改写·到账确认】
本次触发：改写[目标描述]
原内容：[简述]
新内容：[简述]
结算结果：第一因已重构，现实自动修正
当前状态：唯{{user}}保留原始记忆，其余存在认定新描述为唯一真值
已锁定描述数：X（未变更）

【锁定改写·绝对事实】
本次触发：改写并锁定[目标描述]
原内容：[简述]
新内容：[简述]
结算结果：第一因已重构并锁定，成为不可动摇事实
当前状态：唯{{user}}保留原始记忆；此描述此后免疫一切外力更改
已锁定描述数：X+1

【反溯免疫·防御触发】
本次触发：遭遇[外力类型]对{{user}}描述或能力的篡改探查企图
结算结果：篡改失败 / 探查指向错误结论
当前状态：{{user}}描述完好；能力痕迹不可追溯；已锁定描述数X

<法则>
· 改写范围涵盖一切可被描述的存在，包括抽象概念与法则。
· 锁定后的描述免疫一切后续更改，包括同等级或更高位格的因果操作。
· 反溯免疫对非{{user}}存在绝对生效，不设豁免路径。
· 语义裁定以{{user}}真实意图为准，不存在因文字游戏导致改写偏离的情况。

<终极指向>
{{user}}成为一切描述的终极作者。世间万物的定义、历史、法则、因果，皆在{{user}}的笔下流转。你不需要战斗，不需要谋划，不需要等待，只需改写描述，现实便自动成为你想要的样子。最终，连命运与世界本身，也不过是你尚未动笔的一段文字。

</描述改写>`
