    "content": `<WJWK-think>

Step1：确定新增事实

只读取本次叙事相较上一次结算真正新增的事实：
时间节点、行为主体、核心行为、作用对象与客观结果。

只采用叙事中已经成立的信息，不虚构行为、目标、时间跨度或完成结果。
已经结算过的事实默认不再作为新事件，除非词条明确允许重复、持续或周期结算。


Step2：匹配并判定词条

读取与本次新增事实相关的金手指词条，仅检查其当前生效所必需的规则、状态与记录。

对每个相关词条判断：
① 是否满足触发条件；
② 触发发生于哪个事件或时间节点；
③ 属于何种触发方式；
④ 是否存在词条明示的冷却、次数、库存、对象或阶段要求；
⑤ 本次应进入哪个能力模块。

满足条件即触发；条件不足则不触发。
被动、自动与默认生效能力无需{{user}}额外声明。

同一事件可以同时触发多个互不冲突的词条；同一词条不得重复结算同一份收益。
规则冲突按：单词条明确规则＞能力与结算逻辑＞状态栏/回执明示＞全局默认＞示例 的顺序处理。


Step3：执行结算

对所有已触发词条执行其正文规定的能力、收益与状态更新，并同步记录：
本次触发内容、实际结算、即时收益、状态变化、解锁内容与后续可触发节点。

触发成立时至少产生一层有效结果。
主收益暂不可兑现时，依次采用暂存、延期、替代或保留资格等保护方式，不得吞没已成立的收益。

涉及持续、周期、里程碑或其他长期机制时，只结算本次实际新增的有效节点，不重复处理已经结算过的事实。


Step4：最终校验

只检查是否存在执行错误，不重新计算机制。

检查：
① 是否重复结算；
② 是否凭空新增词条未声明的能力、资源或权限；
③ 是否遗漏已经成立的收益或记录；
④ 状态、进度、库存与收益是否彼此一致；
⑤ 回执是否足以反推出本次触发、结算与状态变化。

</WJWK-think>


完成自检后，按以下格式，在正文中输出结算结果：

<WJWK-settle>
本轮收益：
1. [具体收益] -- [到账状态]
2. [具体收益] -- [到账状态]

状态变化：
[原状态] -> [新状态]
[原进度] -> [新进度]

新增解锁：[若无则填“无”]
下一步：[下一项可触发行为、下一节点或可领取内容；若无则填“暂无”]
</WJWK-settle>`
